&lt;div style=&quot;background-color: #fff; float: right; padding: 0 0 8px 8px&quot;&gt;&lt;table id=&quot;TocContainerTable&quot;&gt;&lt;tr&gt;&lt;td&gt;&lt;div id=&quot;TocContainer&quot;&gt;&lt;p class=&quot;small&quot;&gt;&lt;b&gt;Table of Contents&lt;/b&gt;&lt;span id=&quot;ExpandTocSpan&quot;&gt; [&lt;a href=&quot;#&quot; onclick=&quot;javascript:if(document.getElementById(&#39;Toc&#39;).style[&#39;display&#39;]==&#39;none&#39;) document.getElementById(&#39;Toc&#39;).style[&#39;display&#39;]=&#39;&#39;; else document.getElementById(&#39;Toc&#39;).style[&#39;display&#39;]=&#39;none&#39;; return false;&quot;&gt;Hide/Show&lt;/a&gt;]&lt;/span&gt;&lt;/p&gt;&lt;div id=&quot;Toc&quot;&gt;&lt;p&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Traits_raciaux_standards_2&quot;&gt;Traits raciaux standards&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Traits_raciaux_alternatifs_3&quot;&gt;Traits raciaux alternatifs&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Nouvelles_r&#232;gles_raciales_4&quot;&gt;Nouvelles r&#232;gles raciales&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Dons_0&quot;&gt;Dons&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Objets_magiques_1&quot;&gt;Objets magiques&lt;/a&gt;&lt;br /&gt;&lt;/p&gt;&lt;/div&gt;&lt;/div&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/div&gt;&lt;b&gt;&lt;i&gt;Voir aussi la &lt;a class=&quot;unknownlink&quot; href=&quot;Lashunta.html&quot; title=&quot;Pathfinder-RPG.Lashunta&quot;&gt;fiche de cr&#233;ature&lt;/a&gt; d&#39;un lashunta standard.&lt;/i&gt;&lt;/b&gt;&lt;br /&gt;&lt;br /&gt;Originaires de la plan&#232;te Castrovel, un lashunta voyage parfois sur Golarion pour visiter ses alli&#233;s elfiques.&lt;br /&gt;&lt;br /&gt;&lt;div class=&quot;presentation arrondi&quot;&gt;
&lt;div class=”description”&gt;&lt;b&gt;&lt;i&gt;Source :&lt;/i&gt;&lt;/b&gt; &lt;i&gt;Bestiaire de la mer Int&#233;rieure p.30&lt;/i&gt;&lt;/div&gt;
Les lashuntas sont la race principale de Castrovel, que l&#39;on appelle &#171;  la Plan&#232;te verte  &#187; &#224; cause de ses jungles &#233;touffantes. Alors que les femmes ressemblent &#224; des elfes ou &#224; des humaines id&#233;alis&#233;es (au d&#233;tail pr&#232;s des antennes fr&#233;missantes qui poussent sur leur front), les hommes sont r&#226;bl&#233;s, poilus et larges d&#39;&#233;paule, affichant un comportement violent et querelleur. Les deux genres excellent dans les &#233;tudes et la race peut se vanter de compter un grand nombre de t&#233;l&#233;pathes et de t&#233;l&#233;kin&#233;sistes en plus des utilisateurs de magie plus conventionnelle. Cette capacit&#233; &#224; cr&#233;er des liens mentaux ou empathiques est particuli&#232;rement r&#233;pandue chez les femmes guerri&#232;res qui &#233;tablissent des relations &#233;troites avec leurs montures &#224; l&#39;aspect de sauriens.
&lt;/div&gt;&lt;br /&gt;&lt;a name=&quot;TRAITSSTANDARD&quot;&gt;&lt;/a&gt;
&lt;h2 class=&quot;separator&quot;&gt;Traits raciaux standards&lt;a class=&quot;headeranchor&quot; id=&quot;Traits_raciaux_standards_2&quot; href=&quot;#Traits_raciaux_standards_2&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;&lt;div class=&quot;presentation arrondi ombre espaceliste&quot;&gt;
&lt;ul&gt;&lt;li&gt;&lt;b&gt;+2 &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Intelligence.html&quot; title=&quot;L&amp;#39;Intelligence&quot;&gt;Intelligence&lt;/a&gt;.&lt;/b&gt; Les lashuntas sont pratiquement tous intelligents et avides d&#39;apprendre&lt;/li&gt;&lt;li&gt;&lt;b&gt;Dimorphisme sexuel.&lt;/b&gt; Les hommes et les femmes lashuntas ont un corps et une personnalit&#233; tr&#232;s diff&#233;rents, bien plus que les autres esp&#232;ces humano&#239;des. Les hommes lashuntas sont musculeux (+2 en &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Force.html&quot; title=&quot;La Force&quot;&gt;Force&lt;/a&gt;) et sont souvent irr&#233;fl&#233;chis et inattentifs (-2 en &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Sagesse.html&quot; title=&quot;La Sagesse&quot;&gt;Sagesse&lt;/a&gt;). Les femmes lashuntas, quoique belles et autoritaires (+2 en &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Charisme.html&quot; title=&quot;Le Charisme&quot;&gt;Charisme&lt;/a&gt;), n&#39;ont pas la carrure robuste des hommes (-2 en &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Constitution.html&quot; title=&quot;La Constitution&quot;&gt;Constitution&lt;/a&gt;).&lt;/li&gt;&lt;li&gt;&lt;b&gt;Magie lashunta (5 PR).&lt;/b&gt; Les lashuntas qui poss&#232;dent une valeur d&#39;&lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Intelligence.html&quot; title=&quot;L&amp;#39;Intelligence&quot;&gt;Intelligence&lt;/a&gt; de 11 ou plus gagnent les &lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Magiques-(Capacit&#233;).html&quot; title=&quot;Pouvoirs magiques (Mag)&quot;&gt;pouvoirs magiques&lt;/a&gt; suivants  : &#192; volont&#233; — &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;H&#233;b&#233;tement.html&quot; title=&quot;H&#233;b&#233;tement&quot;&gt;h&#233;b&#233;tement&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Manipulation-&#192;-Distance.html&quot; title=&quot;Manipulation &#224; distance&quot;&gt;manipulation &#224; distance&lt;/a&gt;&lt;/i&gt;  ; 1/jour — &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;tection-De-Pens&#233;es.html&quot; title=&quot;D&#233;tection de pens&#233;es&quot;&gt;d&#233;tection de pens&#233;es&lt;/a&gt;&lt;/i&gt;. Le &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Nls.html&quot; title=&quot;NLS&quot;&gt;niveau de lanceur de sorts&lt;/a&gt; de ces effets est &#233;gal au niveau de personnage du lashunta.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Instruit.&lt;/b&gt; Les lashuntas gagnent un bonus racial de +2 &#224; toutes les comp&#233;tences de &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt;.&lt;/li&gt;&lt;li&gt;&lt;b&gt;T&#233;l&#233;pathie limit&#233;e.&lt;/b&gt; Les lashuntas sont capables de communiquer mentalement avec n&#39;importe quelle cr&#233;ature situ&#233;e dans un rayon de 9 m&#232;tres dont ils partagent la langue. Outre cela, cette capacit&#233; est identique &#224; celle de &lt;a class=&quot;pagelink&quot; href=&quot;T&#233;l&#233;pathie-(Capacit&#233;).html&quot; title=&quot;T&#233;l&#233;pathie (Sur)&quot;&gt;t&#233;l&#233;pathie&lt;/a&gt;.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Langues.&lt;/b&gt; Les lashuntas commencent le jeu en parlant l&#39;elfique et le lashunta. Ceux qui poss&#232;dent une valeur d&#39;&lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Intelligence.html&quot; title=&quot;L&amp;#39;Intelligence&quot;&gt;Intelligence&lt;/a&gt; &#233;lev&#233;e peuvent apprendre d&#39;autres langues de leur choix (sauf les langues secr&#232;tes comme celle des &lt;a class=&quot;pagelink&quot; href=&quot;druide.ashx##LANGUESSUPPLEMENTAIRES&quot; title=&quot;Le druide&quot;&gt;druides&lt;/a&gt;).&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;/div&gt;&lt;br /&gt;&lt;a name=&quot;TRAITSALTERNATIFS&quot;&gt;&lt;/a&gt;
&lt;h2 class=&quot;separator&quot;&gt;Traits raciaux alternatifs&lt;a class=&quot;headeranchor&quot; id=&quot;Traits_raciaux_alternatifs_3&quot; href=&quot;#Traits_raciaux_alternatifs_3&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;Il est possible de choisir les traits raciaux suivants &#224; la place des traits raciaux existants des lashuntas. Consultez votre MJ avant de prendre ces options.&lt;br /&gt;&lt;br /&gt;&lt;u&gt;&lt;i&gt;Remplace &#171; magie lashunta &#187; :&lt;/i&gt;&lt;/u&gt;
&lt;ul&gt;&lt;li&gt;&lt;b&gt;T&#233;l&#233;pathie insidieuse.&lt;/b&gt; Certains lashuntas ont un talent pour manipuler l&#39;esprit de ceux avec qui ils communiquent par t&#233;l&#233;pathie. Ils b&#233;n&#233;ficient d&#39;un bonus racial de +1 aux tests de comp&#233;tence bas&#233;s sur le &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Charisme.html&quot; title=&quot;Le Charisme&quot;&gt;Charisme&lt;/a&gt; pour influencer tout cr&#233;ature avec qui ils sont en train de communiquer par t&#233;l&#233;pathie. Si un lashunta transmet un ordre par t&#233;l&#233;pathie &#224; une cr&#233;ature charm&#233;e ou domin&#233;e, il b&#233;n&#233;ficie d&#39;un bonus racial de +1 aux tests de Charisme pour contraindre la cr&#233;ature &#224; suivre cet ordre. Ce trait racial remplace magie lashunta.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;
&lt;h2 class=&quot;separator&quot;&gt;Nouvelles r&#232;gles raciales&lt;a class=&quot;headeranchor&quot; id=&quot;Nouvelles_r&#232;gles_raciales_4&quot; href=&quot;#Nouvelles_r&#232;gles_raciales_4&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;Voici les options accessibles aux lashuntas, d’autres races adapt&#233;es peuvent s’en servir si le MJ donne son accord.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Dons&lt;a class=&quot;headeranchor&quot; id=&quot;Dons_0&quot; href=&quot;#Dons_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;&lt;table CLASS=&quot;tablo centre autoalt toutgauche&quot;&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td WIDTH=&quot;25%&quot;&gt;Dons&lt;/td&gt;&lt;td WIDTH= &quot;6%&quot;&gt;Source&lt;/td&gt;&lt;td WIDTH=&quot;25%&quot;&gt;Conditions&lt;/td&gt;&lt;td WIDTH=&quot;44%&quot;&gt;Avantages&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Connexion-Mentale-Alien.html&quot; title=&quot;Connexion mentale alien&quot;&gt;Connexion mentale alien&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;ISR&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Andro&#239;de-(Race).html&quot; title=&quot;Les andro&#239;des&quot;&gt;Andro&#239;de&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Kasatha-(Race).html&quot; title=&quot;Les kasathas&quot;&gt;kasatha&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Lashunta-(Race).html&quot; title=&quot;Les lashuntas&quot;&gt;lashunta&lt;/a&gt;, ou &lt;a class=&quot;pagelink&quot; href=&quot;Triaxien-(Race).html&quot; title=&quot;Les triaxiens&quot;&gt;triaxien&lt;/a&gt;&lt;/td&gt;&lt;td&gt;+4 aux jets de sauvegarde contre les effets mentaux et les scrutations&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;br /&gt;&lt;table width=&quot;100%&quot;&gt;&lt;tr&gt;&lt;td width=&quot;49%&quot;&gt;
&lt;h3 class=&quot;separator&quot;&gt;Objets magiques&lt;a class=&quot;headeranchor&quot; id=&quot;Objets_magiques_1&quot; href=&quot;#Objets_magiques_1&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Diad&#232;me-De-L&#233;missaire-Interplan&#233;taire.html&quot; title=&quot;Diad&#232;me de l&amp;#39;&#233;missaire interplan&#233;taire&quot;&gt;Diad&#232;me de l&#39;&#233;missaire interplan&#233;taire&lt;/a&gt; &lt;i&gt;(ISR)&lt;/i&gt;&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;/td&gt;&lt;td width=&quot;1%&quot;&gt;
&lt;td style=&quot;border-left:1px solid #4b3124;width=&quot; width=&quot;1%&quot;&gt;&lt;/td&gt;
&lt;/td&gt;&lt;td width=&quot;49%&quot;&gt;&lt;br /&gt;&lt;br /&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
